import {GRAD_GROUPS,ORIGIN_GROUPS,CHECK_STATES,FACULTY_TYPES,facultyRegion,graduationGroup,originGroup,receivingSchools,receivingProgress,filterReceivingSchools,receivingCsv,filterFaculty,facultyCsv,hasDatedCareer,facultyHasConflict} from './faculty.js?v=1.1.1';

const TRACKS={marketing:'Marketing',qm:'Quantitative Marketing',cb:'Consumer Behavior',strategy:'Strategy',io:'Economics / IO',empirical_io:'Empirical IO',theory_io:'Theory IO'};
const EVENT_TYPES={academic:'Academic appointment',faculty:'Faculty appointment',current_appointment:'Appointment at source check',joined_institution:'Joined institution',academic_administration:'Academic leadership',named_chair:'Named chair',visiting:'Visiting appointment',postdoc:'Postdoctoral appointment',industry:'Industry appointment',research:'Research appointment',announced_appointment:'Announced appointment',first_job:'First job',subsequent_job:'Later appointment',promotion:'Promotion'};
const STATUS={current_at_check:'Current at the source check',official_directory:'Official directory',indexed_reference:'Official index reference',directory_membership_unreconciled:'Directory membership unresolved',announced_future:'Announced · arrival not verified',historical_cv_snapshot:'Historical CV snapshot',historical_interval:'Historical interval',award_not_verified:'Doctoral training confirmed · award not verified',training_only:'Doctoral training only',checked:'Checked',link_recorded:'Link recorded · content not verified',indexed_official_text:'Official search-index text'};
const FIELD_NAMES={name:'Name',aliases:'Public aliases',homepage:'Homepage',cv_url:'CV',phd:'Doctoral degree',school:'Institution',program:'Program',region:'Region',year:'Year',date:'Date',current:'Current appointment',role:'Official title',start_year:'Start year',end_year:'End year',start_date:'Start date',end_date:'End date',institution:'Institution',career_events:'Career segment',additional_degrees:'Other degree',other_degrees:'Other degree',biography:'Biography',tracks:'Research track',fields:'Research field',research_inference:'Provisional classification',verification:'Verification',status:'Status',membership:'Membership',directory_membership:'Directory membership',live_source:'Live source',tenure_status:'Tenure status'};
const ioSupplement=p=>p.faculty_scope==='economics_io_supplement'||['MO','AU'].includes(p.current.region)&&(p.tracks||[]).includes('io')&&!(p.tracks||[]).includes('marketing');
const readable=v=>STATUS[v]||String(v||'Unknown').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const fieldLabel=v=>String(v||'Biography').split('.').map(k=>/^\d+$/.test(k)?`#${Number(k)+1}`:FIELD_NAMES[k]||readable(k)).join(' / ');
const sourceHost=v=>{try{return new URL(v).hostname.replace(/^www\./,'')}catch{return 'Public source'}};

export function mountFaculty(root,catalog,openPerson,ui){
 const {esc,external,option}=ui,archive=catalog.faculty,people=archive.people,hosts=receivingSchools(catalog),schools=receivingProgress(catalog),regions=[...new Set(hosts.map(h=>h.region))];
 const defaults={view:'people',q:'',region:'all',host:'all',grad:'all',origin:'all',track:'all',gap:'all',id:'',type:'all',degreeYear:'all',career:'all',sort:'name',personPage:'1',school:'',schoolRegion:'all',schoolState:'all',schoolQ:'',schoolSort:'checked',page:'1'};
 const params=new URLSearchParams(location.hash.split('?')[1]||''),state={...defaults};
 for(const k of Object.keys(defaults))if(params.has('faculty_'+k))state[k]=params.get('faculty_'+k);
 if(!params.has('faculty_view')&&['school','schoolRegion','schoolState','schoolQ','schoolSort','page'].some(k=>params.has('faculty_'+k)))state.view='progress';
 if(!params.has('faculty_view')&&['id','q','region','host','grad','origin','track'].some(k=>params.has('faculty_'+k)))state.view='people';
 if(!['progress','people'].includes(state.view))state.view='people';
 if(!['all','overseas','expanded',...regions].includes(state.schoolRegion))state.schoolRegion='all';
 if(!['all','started',...Object.keys(CHECK_STATES)].includes(state.schoolState))state.schoolState='all';
 if(!schools.some(h=>h.id===state.school))state.school='';
 const started=schools.filter(h=>h.started),complete=schools.filter(h=>h.state==='complete'),linked=people.filter(p=>p.placement_id);
 const overseas=schools.filter(h=>['US','CA','HK','SG'].includes(h.region)),expanded=schools.filter(h=>['MO','AU'].includes(h.region)),mainland=schools.filter(h=>h.region==='CN'),years=[...new Set(people.map(p=>p.phd?.year).filter(Number.isInteger))].sort((a,b)=>b-a);
 const windowYears=[...(catalog.history_years||[])].sort((a,b)=>a-b),windowLabel=windowYears.length?`${windowYears[0]}–${windowYears.at(-1)}`:'the archive window';
 const date=v=>esc(v||'Not checked'),schoolName=h=>h.school||h.label||h.id;
 const button=(label,action,extra='')=>`<button type="button" class="text-button" ${action} ${extra}>${label}</button>`;
 const badge=h=>`<span class="faculty-state ${h.state}">${CHECK_STATES[h.state]}</span>`;
 const metric=(key,label,value,detail)=>`<button type="button" class="faculty-metric" data-metric="${key}"><span>${label}</span><strong>${value}</strong><span>${detail} <span aria-hidden="true">↗</span></span></button>`;
 function download(content,name){const url=URL.createObjectURL(new Blob([content],{type:name.endsWith('.json')?'application/json;charset=utf-8':'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
 function sync(){const query=new URLSearchParams();for(const [k,v] of Object.entries(state))if(v!==defaults[k])query.set('faculty_'+k,v);history.replaceState(null,'','#faculty'+(query.size?'?'+query:''))}
 function showPeople(patch={}){Object.assign(state,{view:'people',q:'',region:'all',host:'all',grad:'all',origin:'all',track:'all',gap:'all',type:'all',degreeYear:'all',career:'all',personPage:'1',id:''},patch);render();root.querySelector('#faculty-content-title')?.focus()}
 function showSchool(id,focus=false){const h=schools.find(h=>h.id===id);if(!h)return;if(state.view==='people'||!filterReceivingSchools(schools,{region:state.schoolRegion,state:state.schoolState,q:state.schoolQ}).some(h=>h.id===id))Object.assign(state,{schoolRegion:h.region,schoolState:'all',schoolQ:'',page:'1'});state.school=id;state.view='progress';render();if(focus)root.querySelector('#faculty-school-title')?.focus()}
 root.innerHTML=`<div class="faculty-workspace"><div class="page-top faculty-head"><div><p class="eyebrow">PEOPLE & CAREER EVIDENCE</p><h1>Faculty directory<span class="title-dot">.</span></h1><p class="page-subtitle">Find faculty, trace doctoral origins, and inspect the evidence behind career histories.</p></div><span class="outline-badge">Last data review ${date(archive.updated_at)}</span></div><div class="faculty-view-switch" role="tablist" aria-label="Faculty directory views"><button type="button" role="tab" id="faculty-tab-people" data-faculty-view="people" aria-controls="faculty-content">People <span>${people.length}</span></button><button type="button" role="tab" id="faculty-tab-progress" data-faculty-view="progress" aria-controls="faculty-content">School coverage <span>${schools.length}</span></button><p>Faculty records are separate from placement cohorts.</p></div><div class="faculty-metrics" aria-label="Faculty coverage overview">${metric('people','Faculty records',people.length,`${new Set(people.map(p=>p.host_id)).size} host schools represented`)}${metric('complete','Directories reconciled',`${complete.length}<small> / ${schools.length}</small>`,'Within the stated scope and snapshot')}${metric('started','Schools checked',`${started.length}<small> / ${schools.length}</small>`,`${overseas.filter(h=>h.started).length}/${overseas.length} original · ${expanded.filter(h=>h.started).length}/${expanded.length} added · ${mainland.filter(h=>h.started).length}/${mainland.length} mainland`)}${metric('linked','Linked placement records',linked.length,'Original first-job records retained')}</div><div id="faculty-content" role="tabpanel"></div></div>`;
 const content=root.querySelector('#faculty-content');
 function sourceLinks(sources,label='Source'){return (sources||[]).map((s,i)=>external(typeof s==='string'?s:s.url,`${label} ${i+1}`)).join(' · ')}
 function originalNotes(text){return text?`<div class="faculty-original"><span class="faculty-source-label">Original source notes</span>${Array.isArray(text)?`<ul>${text.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p>${esc(text)}</p>`}</div>`:''}
 function pagination(page,pages,kind,total,size){return `<div class="faculty-pagination"><span>Page ${page} of ${pages} · ${total}${kind==='people'?` · up to ${size} per page`:''}</span><div><button type="button" class="button secondary" data-${kind}-page="${page-1}" ${page===1?'disabled':''}>Previous</button><button type="button" class="button secondary" data-${kind}-page="${page+1}" ${page===pages?'disabled':''}>Next</button></div></div>`}
 function updateDetails(){
  const f=catalog.faculty_followup_update,n=catalog.faculty_update,e=catalog.faculty_extension_update;
  return `<details class="faculty-update"><summary>Data updates & verification method</summary><div class="faculty-update-body">${e?`<p><strong>Macao & Australia extension · ${esc(e.as_of)}</strong></p><p>${e.counts.new_people} new profiles across ${e.counts.checked_schools} / ${e.counts.target_schools} selected schools; ${e.counts.reconciled_schools} directories reconciled within their declared scope. PhD years known / unknown: ${e.counts.phd_year_known} / ${e.counts.phd_year_unknown}. Profiles with dated careers: ${e.counts.dated_career} / ${e.counts.people}.</p><p>${esc(e.selection_rule)}</p><p>${external('https://github.com/zyx-dirtystar/mkt-io-placement/blob/main/docs/FACULTY-MACAO-AUSTRALIA-2026-10-23.md','Extension audit & remaining gaps')} · ${sourceLinks(e.sources,'Selection source')}</p>`:''}${f?`<p><strong>Historical follow-up · ${esc(f.as_of)} · ${f.baseline.people} existing records</strong></p><p>Unknown PhD award year: ${f.baseline.degree_year_unknown} → ${f.existing.degree_year_unknown}. No dated career segment: ${f.baseline.dated_career_missing} → ${f.existing.dated_career_missing}. Reconciled North American directories: ${f.baseline.na_directory_aligned} → ${f.counts.na_directory_aligned} / 50.</p><div class="faculty-inline-actions">${button(`New PhD years (${f.existing.degree_years_added})`,'data-gap="degree_added"')}${button(`Newly dated careers (${f.existing.dated_career_added})`,'data-gap="career_added"')}${button('Unresolved conflicts','data-gap="conflict"')}${external('https://github.com/zyx-dirtystar/mkt-io-placement/blob/main/docs/FACULTY-FOLLOWUP-2026-10-22.md','Follow-up audit')}</div><p>${f.counts.new_people} new profiles are reported separately from this existing-record comparison.</p>`:''}${n?`<details><summary>Earlier North America expansion</summary><p>${n.counts.target_started} / ${n.baseline.remaining_na} schools checked; ${n.counts.target_aligned} directories reconciled; ${n.counts.new_people} records added. Among ${n.baseline.people} existing records, ${n.existing.degree_years_added} doctoral award years and ${n.existing.expanded_career_people} career histories were supplemented. ${external('https://github.com/zyx-dirtystar/mkt-io-placement/blob/main/docs/FACULTY-NA-UPDATE-2026-10-22.md','Expansion audit')}</p></details>`:''}<p>A reconciled directory confirms its declared faculty scope on a stated observation date. It does not establish complete biographies or a graduating cohort. A dated career segment may describe an appointment, postdoc, visit or industry role; it does not establish a complete career.</p><p>Scheduled source checks flag changes and unavailable links for review. Confirmed facts change after review and release. ${external('https://github.com/zyx-dirtystar/mkt-io-placement/actions/workflows/source-checks.yml','Source-check runs')} · <a href="#coverage">Doctoral cohort coverage</a></p></div></details>`;
 }
 function schoolDetail(h){
  const roster=h.check?.roster,knownSchool=h.people.filter(p=>p.phd?.school&&p.phd?.verification_status!=='training_only').length,knownYear=h.people.filter(p=>Number.isInteger(p.phd?.year)).length,dated=h.people.filter(hasDatedCareer).length,supplements=h.people.filter(p=>ioSupplement(p)).length;
  return `<section class="faculty-school-detail" aria-labelledby="faculty-school-title"><div class="faculty-detail-top"><div><p class="eyebrow">SCHOOL CHECK · ${esc(facultyRegion(h.region))}</p><h2 id="faculty-school-title" tabindex="-1">${esc(schoolName(h))}</h2></div>${button('Close','data-close-school',`aria-label="Close verification details for ${esc(schoolName(h))}"`)}</div><div class="faculty-detail-status">${badge(h)}<span>Latest check ${date(h.checked_at)}</span><span>Confirmed roster size: ${h.roster_total??'Unknown'}</span></div><p>${h.state==='complete'?`The official directory has been reconciled within its declared scope. Snapshot: ${date(roster.checked_at)}. This describes the roster, not individual career completeness.`:h.people.length?'Individual faculty records are available. Department-wide roster completeness has not been confirmed.':'No faculty records have been verified for this school. An unstarted check is not a count of zero faculty.'}</p><div class="faculty-detail-columns"><div><h3>Faculty records · ${h.people.length}</h3>${supplements?`<p class="muted">Includes ${supplements} separately scoped Economics IO profiles. These do not enlarge or establish completeness of the Marketing roster.</p>`:''}${h.people.length?`<ul class="faculty-member-list">${h.people.map(p=>`<li>${button(esc(p.name),`data-show-person="${esc(p.id)}"`)}<span>${esc(p.phd?.school||'PhD institution unknown')} · ${p.phd?.year||'Award year unknown'}</span></li>`).join('')}</ul>${button(`Browse all ${h.people.length} records →`,`data-school-people="${esc(h.id)}"`)}`:'<p class="muted">Faculty count remains unknown until the official roster is checked.</p>'}</div><div><h3>Biography coverage</h3><div class="faculty-detail-stats">${[[knownSchool,'PhD institution known'],[knownYear,'PhD award year known'],[dated,'At least one dated career segment']].map(([n,t])=>`<div><strong>${n}<small> / ${h.people.length}</small></strong><span>${t}</span></div>`).join('')}</div>${h.missing_year?button(`${h.missing_year} unknown PhD years →`,`data-school-gap="${esc(h.id)}"`):''}<h3>${h.state==='complete'?'Roster evidence':'What remains to verify'}</h3>${roster?.scope?`<p class="faculty-source-label">Declared scope · original wording</p><p>${esc(roster.scope)}</p>`:''}${h.state==='complete'?sourceLinks(roster.evidence,'Roster source'):'<p class="muted">Confirm the department and appointment scope, reconcile all directory members, and record inclusion and exclusion decisions. Collected profiles do not establish department size.</p>'}${roster?.exclusions?.length?`<details><summary>Excluded or separately counted · ${roster.exclusions.length}</summary><p class="faculty-source-label">Original source notes</p><ul>${roster.exclusions.map(x=>`<li>${esc(x.name||x.category||'Group')}: ${esc(x.reason||x.role||'Separately counted')}</li>`).join('')}</ul></details>`:''}${h.check?.access_limitations?.length?`<h3>Access limitations</h3><ul>${h.check.access_limitations.map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`:''}<h3>School sources</h3>${h.check?.sources?.length?sourceLinks(h.check.sources):'<p class="muted">No school-level evidence registered. Individual sources appear in faculty records.</p>'}${originalNotes(h.check?.notes)}</div></div></section>`;
 }
 function progressMarkup(){
  const rows=filterReceivingSchools(schools,{region:state.schoolRegion,state:state.schoolState,q:state.schoolQ,sort:state.schoolSort});
  const pages=Math.max(1,Math.ceil(rows.length/10));state.page=String(Math.min(pages,Math.max(1,parseInt(state.page,10)||1)));const page=Number(state.page),visible=rows.slice((page-1)*10,page*10);
  return `<section class="panel faculty-board"><div class="panel-heading"><div><p class="eyebrow">SCOPE & EVIDENCE</p><h2 id="faculty-content-title" tabindex="-1">School coverage</h2></div><span class="faculty-state partial">${schools.length-started.length} not yet started</span></div><p class="faculty-intro">The original scope comprises 50 North American Marketing schools, five in Hong Kong, three in Singapore and nine designated mainland schools. The independently versioned extension adds three Macao universities and Australia’s eight Go8 members. A checked school can still have an incomplete roster.</p><details class="faculty-scope-definition"><summary>Selection rules & scope version</summary>${(archive.receiving_scope.extension_plans||[]).map(p=>`<p><strong>${esc(p.id)}</strong> · selected ${esc(p.selected_at)}</p><p>${esc(p.selection_rule)}</p><p>${esc(p.person_rule)}</p><p>${sourceLinks(p.sources,'Scope source')}</p>`).join('')}<p>The original 58-program doctoral placement scope is retained. Receiving-side faculty records do not enlarge placement cohorts.</p></details><div class="faculty-region-grid">${regions.map(r=>{const hs=schools.filter(h=>h.region===r),n=hs.filter(h=>h.started).length;return `<button type="button" class="faculty-region ${state.schoolRegion===r?'selected':''}" data-school-region="${r}" aria-pressed="${state.schoolRegion===r}"><span>${facultyRegion(r)}</span><strong>${n}<small> / ${hs.length} checked</small></strong><span class="faculty-meter" aria-hidden="true"><i style="width:${hs.length?100*n/hs.length:0}%"></i></span><span class="faculty-region-note">${hs.filter(h=>h.state==='complete').length} reconciled · ${hs.reduce((s,h)=>s+h.people.length,0)} records</span></button>`}).join('')}</div></section><section class="panel faculty-schools"><div class="panel-heading"><div><p class="eyebrow">BROWSE RECEIVING SCHOOLS</p><h2>Check a school</h2></div><button type="button" class="button secondary" id="faculty-school-export">Export coverage CSV</button></div><form id="faculty-school-filters" class="faculty-school-filters"><label class="search"><span aria-hidden="true">⌕</span><input type="search" name="schoolQ" value="${esc(state.schoolQ)}" aria-label="Search schools or faculty names" placeholder="School or faculty name"></label><label class="filter-label">Region<select name="schoolRegion">${[['all',`All ${schools.length} schools`],['overseas',`Original overseas scope · ${overseas.length} schools`],['expanded',`Macao & Australia · ${expanded.length} schools`],...regions.map(r=>[r,facultyRegion(r)])].map(([v,t])=>option(v,t,state.schoolRegion)).join('')}</select></label><label class="filter-label">Verification status<select name="schoolState">${[['all','All statuses'],['started','Checks started'],...Object.entries(CHECK_STATES)].map(([v,t])=>option(v,t,state.schoolState)).join('')}</select></label><label class="filter-label">Sort by<select name="schoolSort">${[['checked','Latest check first'],['name','School name A–Z']].map(([v,t])=>option(v,t,state.schoolSort)).join('')}</select></label></form><div class="faculty-results-meta" role="status"><span>${rows.length} schools match · ${rows.filter(h=>h.started).length} checked</span>${button('Reset school filters','data-reset-schools')}</div>${state.school?schoolDetail(schools.find(h=>h.id===state.school)):''}${visible.length?`<div class="table-scroll"><table class="faculty-school-table"><caption class="sr-only">School verification progress. Counts remain unknown for unstarted schools.</caption><thead><tr><th scope="col">Receiving school</th><th scope="col">Verification</th><th scope="col">Records / linked</th><th scope="col">Latest check</th><th scope="col"><span class="sr-only">Details</span></th></tr></thead><tbody>${visible.map(h=>`<tr class="${state.school===h.id?'selected':''}"><th scope="row">${button(esc(schoolName(h)),`data-open-school="${esc(h.id)}"`)}<span class="cell-note">${facultyRegion(h.region)}</span></th><td data-label="Verification">${badge(h)}</td><td data-label="Records / linked">${h.started?`<strong>${h.people.length}</strong> / ${h.linked}`:'<span class="muted">Not checked · count unknown</span>'}</td><td data-label="Latest check">${date(h.checked_at)}</td><td>${button('View check →',`data-open-school="${esc(h.id)}"`,`aria-label="View verification for ${esc(schoolName(h))}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>No schools match these filters</h3><p>Try another region, status or school name.</p></div>'}${pagination(page,pages,'school',`${rows.length} schools`,10)}</section>${updateDetails()}`;
 }
 function careerEvidence(p){
  const events=p.career_events||[],gaps=p.unknowns||[],status=p.current.appointment_status==='on_leave'?'On leave from this appointment; concurrent roles appear below.':p.current.status==='indexed_reference'?'Official index reference; live membership has not been rechecked.':p.current.status==='directory_membership_unreconciled'?'Directory membership differs across sources and remains unresolved.':p.current.status==='announced_future'?'Announced appointment; arrival has not been verified.':'';
  return `<div class="faculty-career">${status?`<p class="faculty-status-note">${esc(status)}</p>`:''}${p.phd?.degree_status==='award_not_verified'?'<p class="faculty-status-note">Doctoral training is confirmed; degree award remains unverified.</p>':''}<details><summary>Career evidence <span>${events.length} segments</span></summary><p class="muted">Sourced segments do not establish a complete career. The earliest segment is not automatically a first job. Historical CVs apply only to their recorded version.</p>${events.length?`<ol class="faculty-career-list">${events.toSorted((a,b)=>String(a.start_date||a.start||a.start_year||'9999').localeCompare(String(b.start_date||b.start||b.start_year||'9999'))).map(e=>{const start=e.start_date||e.start||e.start_year||'Start unknown',snapshot=e.source_snapshot_only||/snapshot/.test(e.status||''),end=e.end_date||e.end||e.end_year||(snapshot?'At source snapshot':e.type==='current_appointment'?'Current at check':'End not stated');return `<li><div class="faculty-event-date">${esc(start)} <span>→</span> ${esc(end)}</div><strong>${esc(e.institution||'Institution unknown')}</strong><p>${esc(e.role||e.title||EVENT_TYPES[e.type]||readable(e.type))}</p><span class="faculty-source-label">${esc(EVENT_TYPES[e.type]||readable(e.type))}${e.source_date?' · Source version '+esc(e.source_date):''}${e.checked_at?' · Checked '+esc(e.checked_at):''}</span><div>${sourceLinks(e.source_urls,'Evidence')}</div>${e.evidence||e.quote?`<details class="faculty-source-excerpt"><summary>Original source excerpt</summary><blockquote>${esc(e.evidence||e.quote)}</blockquote></details>`:''}</li>`}).join('')}</ol>`:'<p>No career history is recorded. Directory membership does not establish appointment dates.</p>'}</details><details class="${facultyHasConflict(p)?'faculty-conflict':''}"><summary>Gaps & source conflicts <span>${gaps.length} notes</span></summary><p class="faculty-source-label">Original source notes · field labels translated for navigation</p>${gaps.length?`<ul class="faculty-gap-notes">${gaps.map(g=>`<li><strong>${esc(fieldLabel(g.field))}</strong><p>${esc(g.reason||g)}${g.values?' ('+esc(JSON.stringify(g.values))+')':''}</p>${g.source_urls?.length?sourceLinks(g.source_urls,'Evidence'):''}${g.field?`<code>${esc(g.field)}</code>`:''}</li>`).join('')}</ul>`:'<p>No additional gap notes are registered. This does not confirm a complete career history.</p>'}</details></div>`;
 }
 function personCard(p){
  const extraDegrees=p.additional_degrees||p.other_degrees||[];
  return `<article class="faculty-card"><div class="faculty-person-top"><div><h3 id="faculty-person-${esc(p.id)}" tabindex="-1">${esc(p.name)}</h3>${p.aliases?.length?`<p class="cell-note">${esc(p.aliases.join(' · '))}</p>`:''}<p class="faculty-card-host">${esc(p.current.institution)} · ${facultyRegion(p.current.region)}</p></div><span class="faculty-state ${p.placement_id?'partial':'not_started'}">${p.placement_id?'Placement linked':'Faculty record'}</span></div><div class="track-tags">${ioSupplement(p)?'<span class="tag">Economics IO · supplementary scope</span>':''}<span class="tag">${esc(FACULTY_TYPES[p.faculty_type]||'Research faculty')}</span>${(p.tracks||[]).filter(t=>t!=='marketing').map(t=>`<span class="tag">${esc(TRACKS[t]||readable(t))}</span>`).join('')}${facultyHasConflict(p)?'<span class="tag faculty-warning">Source conflict</span>':''}${p.research_inference?'<span class="tag faculty-warning">Provisional track available</span>':''}</div><dl class="faculty-profile-facts"><div><dt>Current title <span>Source wording</span></dt><dd>${esc(p.current.role||'Title unknown')}<small>Rank start: ${esc(p.current.start_year||'Unknown')} · not a first-job date</small></dd></div><div><dt>Doctoral degree</dt><dd>${esc(p.phd?.school||'Institution unknown')}<small>${esc(p.phd?.program||'Program unknown')} · ${esc(p.phd?.date||p.phd?.year||'Award year unknown')}</small>${p.phd?.reported_year?`<small>Index clue: ${esc(p.phd.reported_year)} · original evidence pending</small>`:''}${p.phd?.defense_year?`<small>Defense: ${esc(p.phd.defense_year)} · award year not verified</small>`:''}${p.phd?.reported_dissertation_year?`<small>Dissertation-supervision year: ${esc(p.phd.reported_dissertation_year)} · award year not verified</small>`:''}${extraDegrees.map(d=>`<small>Other degree: ${esc(d.degree||'Degree')} · ${esc(d.school||'Institution unknown')} · ${esc(d.program||'Program unknown')} · ${esc(d.date||d.year||'Year unknown')}</small>`).join('')}</dd></div><div><dt>Research <span>Source wording</span></dt><dd>${esc((p.fields||[]).join(' · ')||'Detailed research classification pending')}</dd></div></dl><div class="faculty-links">${p.homepage?external(p.homepage,'Homepage'):''}${p.cv_url?external(p.cv_url,'CV'):''}${p.placement_id?button('Placement history',`data-faculty-person="${esc(p.placement_id)}"`):''}<a href="#faculty?faculty_view=people&faculty_region=all&faculty_id=${encodeURIComponent(p.id)}">Permalink</a>${button('School coverage',`data-open-school="${esc(p.host_id)}"`)}</div>${careerEvidence(p)}<details class="faculty-provenance"><summary>Sources & review notes <span>${date(p.checked_at)}</span></summary>${originalNotes(p.notes)}${p.followup_review?.notes?`<p class="faculty-source-label">Follow-up review · original notes</p><p>${esc(p.followup_review.notes)}</p>`:''}${p.backfill_review?.notes?`<p class="faculty-source-label">Backfill review · original notes</p><p>${esc(p.backfill_review.notes)}</p>`:''}${p.research_inference?`<p><strong>Provisional classification:</strong> ${esc((p.research_inference.tracks||[]).map(t=>TRACKS[t]||readable(t)).join(' · '))}</p>${originalNotes(p.research_inference.reason)}`:''}<ul class="source-list faculty-source-list">${(p.sources||[]).map((s,i)=>`<li>${external(s.url,`Source ${i+1} · ${sourceHost(s.url)}`)}<p class="cell-note">${esc((s.supports||[]).map(fieldLabel).join(' · ')||'Record-level evidence')}</p><p class="cell-note">${s.checked_at?'Checked '+esc(s.checked_at):'Check date not recorded'}${s.source_date?' · Source date '+esc(s.source_date):''}${s.access_status?' · '+esc(readable(s.access_status)):''}${/index/i.test([s.verification_status,s.access_status,s.read_status].join(' '))?' · Index reference; see original retrieval status':''}</p>${s.quote?`<blockquote><span class="faculty-source-label">Original source excerpt</span>${esc(s.quote)}</blockquote>`:''}${s.label||s.locator?`<p class="cell-note">Original source label / locator: ${esc([s.label,s.locator].filter(Boolean).join(' · '))}</p>`:''}</li>`).join('')}</ul></details></article>`;
 }
 function peopleMarkup(){
  const select=(name,label,options)=>`<label class="filter-label">${label}<select name="${name}">${options.map(([v,t])=>option(v,t,state[name])).join('')}</select></label>`,recent=people.filter(p=>graduationGroup(p,windowYears)==='recent').length,unknown=people.filter(p=>!Number.isInteger(p.phd?.year)).length,dated=people.filter(hasDatedCareer).length;
  return `<form id="faculty-filters" class="filter-panel faculty-people-form"><div class="filter-top"><div><p class="eyebrow">FIND A PERSON</p><h2>Search the faculty directory</h2></div><label class="search"><span aria-hidden="true">⌕</span><input name="q" value="${esc(state.q)}" aria-label="Search faculty by name, doctoral institution or research" placeholder="Name, PhD institution, research" type="search"></label></div><div class="filter-grid">${select('region','Appointment region',[['all','All regions'],['overseas','Original US / CA / HK / SG scope'],['expanded','Macao & Australia · added scope'],...regions.map(r=>[r,facultyRegion(r)])])}${select('host','Receiving school',[['all','All receiving schools'],...hosts.map(h=>[h.id,schoolName(h)])])}${select('track','Verified research track',[['all','All research tracks'],...Object.entries(TRACKS)])}${select('degreeYear','PhD award year',[['all','All award years'],...years.map(y=>[String(y),String(y)])])}</div><details class="faculty-extra-filters" ${['type','grad','origin','career','gap'].some(k=>state[k]!=='all')?'open':''}><summary>More filters ${['type','grad','origin','career','gap'].some(k=>state[k]!=='all')?'<span>'+['type','grad','origin','career','gap'].filter(k=>state[k]!=='all').length+' active</span>':''}</summary><div class="filter-grid">${select('type','Appointment group',[['all','All appointment groups'],...Object.entries(FACULTY_TYPES)])}${select('grad','Degree-year group',[['all','All degree-year groups'],...Object.entries(GRAD_GROUPS)])}${select('origin','Doctoral origin',[['all','All doctoral origins'],...Object.entries(ORIGIN_GROUPS)])}${select('career','Career evidence',[['all','All career records'],['dated','At least one dated segment'],['missing','No dated segment yet']])}${select('gap','Verification & gaps',[['all','All verification states'],['conflict','Unresolved source conflict'],['degree_school','PhD institution unknown'],['degree_year','PhD award year unknown'],['career','No dated career segment'],['cv','CV link not recorded'],['role_year','Current rank start unknown'],['linked','Linked to placement record'],['unlinked','No placement link'],['degree_added','PhD year added in latest follow-up'],['career_added','First dated segment in latest follow-up']])}</div></details><div class="filter-bottom"><span>Search includes public aliases. Unknown dates remain unknown.</span>${button('Reset filters','data-reset-people')}</div></form><div class="faculty-scope-strip"><span><strong>${recent}</strong> PhDs awarded ${esc(windowLabel)}</span><span><strong>${unknown}</strong> award years unknown</span><span><strong>${dated}</strong> records with dated segments</span><span>All ${people.length} collected records · separate from placement cohorts</span></div><div id="faculty-results" aria-live="polite"></div><details class="faculty-coverage-gaps"><summary>Explore missing evidence</summary><div class="faculty-gap-list">${[['career','No dated career segment',people.filter(p=>!hasDatedCareer(p)).length],['degree_year','PhD award year unknown',unknown],['cv','CV link not recorded',people.filter(p=>!p.cv_url).length],['role_year','Current rank start unknown',people.filter(p=>!Number.isInteger(p.current.start_year)).length]].map(([k,label,n])=>`<button type="button" data-gap="${k}"><span>${label}</span><strong>${n}<small> / ${people.length} →</small></strong></button>`).join('')}</div><p class="muted">Counts describe collected profiles. Faculty counts at unstarted schools remain unknown. ${button(`View ${people.length-linked.length} records without placement links →`,'data-gap="unlinked"')}</p></details>${updateDetails()}`;
 }
 function renderPeople(){
  const rows=filterFaculty(people,state,catalog),pages=Math.max(1,Math.ceil(rows.length/20));state.personPage=String(Math.min(pages,Math.max(1,parseInt(state.personPage,10)||1)));const page=Number(state.personPage),visible=rows.slice((page-1)*20,page*20);sync();
  const target=content.querySelector('#faculty-results');target.innerHTML=`<section class="panel faculty-result-panel"><div class="panel-heading"><div><p class="eyebrow">FACULTY RECORDS</p><h2 id="faculty-content-title" tabindex="-1">${rows.length} ${rows.length===1?'person':'people'}${state.id?' · direct record link':' match'}</h2></div><label class="faculty-sort">Sort by<select id="faculty-people-sort" aria-label="Sort faculty records">${[['name','Name A–Z'],['checked','Latest review first']].map(([v,t])=>option(v,t,state.sort)).join('')}</select></label></div>${state.id?`<div class="faculty-direct-link">Viewing one fixed record. ${button('Browse the full directory →','data-clear-person')}</div>`:''}<div class="faculty-actions"><button type="button" class="button secondary" id="faculty-export">Export CSV</button><button type="button" class="button secondary" id="faculty-export-json">Export JSON with evidence</button><span>Exports include these filters, dates, unknowns and source evidence.</span></div>${rows.length?`<div class="faculty-cards">${visible.map(personCard).join('')}</div>`:'<div class="empty-state"><h3>No collected records match</h3><p>Try fewer filters or check a school’s coverage. An unstarted check does not mean there are no relevant faculty.</p><div class="faculty-inline-actions"><button type="button" class="button secondary" data-clear-person>Reset people filters</button><button type="button" class="button secondary" data-back-progress>View school coverage</button></div></div>'}${pagination(page,pages,'people',`${rows.length} records`,20)}</section>`;
  target.querySelectorAll('[data-people-page]').forEach(b=>b.onclick=()=>{state.personPage=b.dataset.peoplePage;renderPeople();content.querySelector('#faculty-content-title').focus()});target.querySelector('#faculty-export').onclick=()=>download(facultyCsv(rows,catalog),'faculty-archive-'+archive.updated_at+'.csv');target.querySelector('#faculty-export-json').onclick=()=>download(JSON.stringify({as_of:archive.updated_at,scope:'Collected receiving-side faculty profiles, separate from placement cohort denominators. Unknown values are retained. Sourced segments do not establish a complete career.',receiving_scope:archive.receiving_scope,filters:{...state},people:rows},null,2),'faculty-archive-'+archive.updated_at+'.json');target.querySelector('#faculty-people-sort').onchange=e=>{state.sort=e.target.value;state.personPage='1';renderPeople();content.querySelector('#faculty-people-sort').focus()};target.querySelectorAll('[data-clear-person]').forEach(b=>b.onclick=()=>showPeople());bindLinks();
 }
 function bindLinks(){content.querySelectorAll('[data-open-school]').forEach(b=>b.onclick=()=>showSchool(b.dataset.openSchool,true));content.querySelectorAll('[data-faculty-person]').forEach(b=>b.onclick=()=>openPerson(b.dataset.facultyPerson));content.querySelectorAll('[data-back-progress]').forEach(b=>b.onclick=()=>{state.view='progress';render();content.querySelector('#faculty-content-title')?.focus()});content.querySelectorAll('[data-gap]').forEach(b=>b.onclick=()=>showPeople({gap:b.dataset.gap}));}
 function render(){
  root.querySelectorAll('[data-faculty-view]').forEach(b=>{const selected=b.dataset.facultyView===state.view;b.classList.toggle('selected',selected);b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1});content.setAttribute('aria-labelledby','faculty-tab-'+state.view);content.innerHTML=state.view==='progress'?progressMarkup():peopleMarkup();sync();
  if(state.view==='people'){const form=content.querySelector('#faculty-filters');form.onsubmit=e=>e.preventDefault();form.onchange=e=>{state[e.target.name]=e.target.value;state.personPage='1';const advanced=form.querySelector('.faculty-extra-filters');const active=['type','grad','origin','career','gap'].filter(k=>state[k]!=='all').length;advanced.querySelector('summary').innerHTML='More filters'+(active?' <span>'+active+' active</span>':'');renderPeople()};form.elements.q.oninput=e=>{if(!e.isComposing){state.q=e.target.value;state.personPage='1';renderPeople()}};content.querySelector('[data-reset-people]').onclick=()=>showPeople();renderPeople();return;}
  const form=content.querySelector('#faculty-school-filters');form.onsubmit=e=>e.preventDefault();
  function updateSchoolFilter(e){if(e.isComposing)return;const name=e.target.name,value=e.target.value,start=e.target.selectionStart,end=e.target.selectionEnd;state[name]=value;state.page='1';state.school='';render();const control=content.querySelector(`[name="${name}"]`);control.focus();if(name==='schoolQ'&&start!==null)control.setSelectionRange(start,end)}
  form.onchange=e=>{if(e.target.name!=='schoolQ')updateSchoolFilter(e)};form.elements.schoolQ.oninput=updateSchoolFilter;content.querySelectorAll('[data-school-region]').forEach(b=>b.onclick=()=>{state.schoolRegion=b.dataset.schoolRegion;state.school='';state.page='1';render();content.querySelector(`[data-school-region="${state.schoolRegion}"]`).focus()});content.querySelector('[data-reset-schools]').onclick=()=>{Object.assign(state,{schoolRegion:'all',schoolState:'all',schoolQ:'',schoolSort:'checked',school:'',page:'1'});render()};content.querySelectorAll('[data-school-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.schoolPage;state.school='';render();content.querySelector('#faculty-school-filters').scrollIntoView({block:'start'})});content.querySelector('#faculty-school-export').onclick=()=>download(receivingCsv(filterReceivingSchools(schools,{region:state.schoolRegion,state:state.schoolState,q:state.schoolQ,sort:state.schoolSort})),'faculty-school-progress-'+archive.updated_at+'.csv');content.querySelector('[data-close-school]')?.addEventListener('click',()=>{const id=state.school;state.school='';render();(content.querySelector(`[data-open-school="${id}"]`)||content.querySelector('[name="schoolQ"]')).focus()});content.querySelectorAll('[data-school-people]').forEach(b=>b.onclick=()=>showPeople({host:b.dataset.schoolPeople}));content.querySelectorAll('[data-school-gap]').forEach(b=>b.onclick=()=>showPeople({host:b.dataset.schoolGap,gap:'degree_year'}));content.querySelectorAll('[data-show-person]').forEach(b=>b.onclick=()=>showPeople({id:b.dataset.showPerson}));bindLinks();
 }
 root.querySelectorAll('[data-faculty-view]').forEach(b=>{b.onclick=()=>{state.view=b.dataset.facultyView;render()};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();state.view=e.key==='Home'?'people':e.key==='End'?'progress':state.view==='people'?'progress':'people';render();root.querySelector('#faculty-tab-'+state.view).focus()}});root.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{const key=b.dataset.metric;if(key==='people'||key==='linked')showPeople(key==='linked'?{gap:'linked'}:{});else{Object.assign(state,{view:'progress',schoolRegion:'all',schoolState:key==='complete'?'complete':'started',schoolQ:'',school:'',page:'1'});render();content.querySelector('#faculty-school-filters').scrollIntoView({block:'start'})}});render();
}
